/**
 * generate-reference.js
 *
 * Generates NEW reference pages (from data/reference.json).
 * Does NOT touch existing /reference/ pages generated by earlier phases.
 *
 * reference/index.html           — hub (lists existing + new reference pages)
 * reference/<new-slug>.html      — individual pages from data/reference.json
 *
 * Idempotent — regenerates on every pipeline run.
 */

'use strict';

const fs   = require('fs');
const path = require('path');
const {
  fill, template, partial, SITE_HEADER, SITE_FOOTER, esc,
  buildBreadcrumb, buildRefContent, writeFile, ROOT,
} = require('./template-utils');

const data = require(path.join(ROOT, 'data', 'reference.json'));
const REF_DIR = path.join(ROOT, 'reference');

// ── Discover existing reference pages ────────────────────────────────────────

function existingRefPages() {
  if (!fs.existsSync(REF_DIR)) return [];
  return fs.readdirSync(REF_DIR)
    .filter(f => f.endsWith('.html') && f !== 'index.html')
    .map(f => {
      const slug = f.replace(/\.html$/, '');
      const title = slug.replace(/-/g, ' ')
        .replace(/\b[a-z]/g, c => c.toUpperCase());
      return { href: `/reference/${slug}`, label: title };
    });
}

// ── Hub page ──────────────────────────────────────────────────────────────────

function generateHub() {
  const existing = existingRefPages();
  const newPages = data.pages || [];
  const allPages = [
    ...existing,
    ...newPages.map(p => ({ href: `/${p.slug}`, label: p.title })),
  ];

  const refCards = allPages.length > 0
    ? allPages.map(p =>
        `      <a href="${p.href}" class="knowledge-card">
        <div class="knowledge-card-title">${esc(p.label)}</div>
      </a>`).join('\n')
    : `      <div class="knowledge-callout">
        <span class="knowledge-callout-icon">&#128197;</span>
        <div><strong>Reference pages are coming.</strong> Use the <a href="/reference/pool-chemistry-reference">Pool Chemistry Reference</a> to get started.</div>
      </div>`;

  const bc = buildBreadcrumb('reference', 'Reference');

  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <link rel="canonical" href="https://waterbalancetools.com/reference/">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Pool Chemistry Reference | WaterBalanceTools</title>
  <meta name="description" content="Reference tables, target ranges, and chemical data for pool and hot tub water chemistry. Ideal ranges for chlorine, pH, alkalinity, hardness, and CYA.">
  <link rel="stylesheet" href="/style.css">
  <link rel="stylesheet" href="/knowledge.css">
  <script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-3974004697476579" crossorigin="anonymous"></script>
  ${bc.schema}
</head>
<body class="knowledge-page reference-hub">
${SITE_HEADER}
${bc.nav}
  <main class="container">
    <section class="knowledge-hub-hero">
      <span class="knowledge-badge knowledge-badge--reference">Reference</span>
      <h1>Pool Chemistry Reference</h1>
      <p>Quick-access reference tables, target ranges, and dosing data for pool and hot tub water chemistry.</p>
    </section>
    <section>
      <h2>All Reference Pages</h2>
      <div class="knowledge-grid knowledge-grid--2col">
${refCards}
      </div>
    </section>
    <section class="link-matrix">
      <h3>Related</h3>
      <ul>
        <li><a href="/academy/">Chemistry Academy</a></li>
        <li><a href="/formulas/">Formula Library</a></li>
        <li><a href="/glossary/">Glossary</a></li>
        <li><a href="/calculators/chemical-calculator">Pool Chemical Calculator</a></li>
      </ul>
    </section>
  </main>
${SITE_FOOTER}
  <script src="/js/nav.js" defer></script>
</body>
</html>`;
}

// ── Individual reference page ─────────────────────────────────────────────────

function generateRefPage(page) {
  const tpl = template('reference-template.html');
  const bc = buildBreadcrumb(page.slug, page.title);

  return fill(tpl, {
    SLUG:              page.slug,
    PAGE_TITLE:        `${page.title} | Reference | WaterBalanceTools`,
    H1_TITLE:          page.title,
    META_DESCRIPTION:  page.description,
    LAST_REVIEWED:     page.lastReviewed || '2026-06-01',
    BREADCRUMB:        bc.nav,
    BREADCRUMB_SCHEMA: bc.schema,
    HERO: fill(partial('knowledge-hero.html'), {
      BADGE:         'Reference',
      BADGE_CLASS:   'knowledge-badge--reference',
      READING_TIME:  page.readingTime || '2 min read',
      LAST_REVIEWED: page.lastReviewed || '2026-06-01',
      TITLE:         esc(page.title),
      SUMMARY:       esc(page.summary || ''),
      CHIPS:         '<a href="#overview" class="knowledge-chip">Overview</a>',
    }),
    CONTENT:           buildRefContent(page),
    SIDEBAR:           '',
    RELATED_TOOLS:     '',
    RELATED_TOPICS:    '',
    KNOWLEDGE_FOOTER:  '',
    SITE_FOOTER:       SITE_FOOTER,
  });
}

// ── Run ───────────────────────────────────────────────────────────────────────

let written = 0;

writeFile(path.join(REF_DIR, 'index.html'), generateHub());
written++;
console.log('  → reference/index.html');

for (const page of (data.pages || [])) {
  const outPath = path.join(ROOT, `${page.slug}.html`);
  writeFile(outPath, generateRefPage(page));
  written++;
  console.log(`  → ${page.slug}.html`);
}

console.log(`generate-reference: wrote ${written} files (${(data.pages || []).length} new reference pages)`);
